import re, glob

def roman_to_int(s):
    vals = {'i':1,'v':5,'x':10,'l':50,'c':100}
    total = 0
    prev = 0
    for ch in reversed(s):
        v = vals[ch]
        if v < prev:
            total -= v
        else:
            total += v
            prev = v
    return total

files = glob.glob('docs/lords-of-cian/chronicles/ozmund-chronicle-*.md')
nums = set()
for f in files:
    m = re.match(r'.*/ozmund-chronicle-([a-z]+)-', f)
    if m:
        roman = m.group(1)
        try:
            n = roman_to_int(roman)
            nums.add(n)
        except KeyError:
            print('bad parse', f)

expected = set(range(1,121))
missing = sorted(expected - nums)
print('total found:', len(nums))
print('missing:', missing)
"

