import re

base = "docs/lords-of-cian/chronicles/"

def sub(path, pairs, literal=True):
    p = base + path
    s = open(p, encoding="utf-8").read()
    orig = s
    for old, new in pairs:
        if literal:
            cnt = s.count(old)
            if cnt == 0:
                print(f"WARN: 0 hits for {old!r} in {path}")
            s = s.replace(old, new)
        else:
            s, n = re.subn(old, new, s)
